namespace benchmark

function sides_are_positive(a: int64, b: int64, c: int64) returns bool:
    if a <= 0:
        return false
    if b <= 0:
        return false
    if c <= 0:
        return false
    return true

function satisfies_triangle_inequality(a: int64, b: int64, c: int64) returns bool:
    if a + b <= c:
        return false
    if a + c <= b:
        return false
    if b + c <= a:
        return false
    return true

function is_valid_triangle(a: int64, b: int64, c: int64) returns bool:
    if not sides_are_positive(a, b, c):
        return false
    if not satisfies_triangle_inequality(a, b, c):
        return false
    return true

function triangle_kind(a: int64, b: int64, c: int64) returns string:
    if not is_valid_triangle(a, b, c):
        return "invalid"
    if a == b and b == c:
        return "equilateral"
    if a == b or a == c or b == c:
        return "isosceles"
    return "scalene"

